package com.cinenest.verification.internal;
import java.sql.*;
import java.time.*;
import java.util.*;
import com.nimbusds.jose.util.JSONObjectUtils;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
@Repository
class JdbcVerificationRepository implements VerificationRepository {
    private final JdbcClient jdbc;
    JdbcVerificationRepository(JdbcClient jdbc){this.jdbc=jdbc;}
    private JdbcClient.StatementSpec sql(String sql,Object... pairs){var query=jdbc.sql(sql);for(int i=0;i<pairs.length;i+=2)query=query.param(pairs[i].toString(),pairs[i+1]);return query;}
    private static Instant instant(ResultSet rs,String column)throws SQLException{var value=rs.getObject(column,OffsetDateTime.class);return value==null?null:value.toInstant();}
    private static Request request(ResultSet r,int i)throws SQLException{return new Request(r.getObject("request_id",UUID.class),r.getObject("owner_id",UUID.class),r.getObject("venue_id",UUID.class),r.getObject("quote_id",UUID.class),r.getObject("policy_id",UUID.class),r.getObject("previous_id",UUID.class),r.getInt("generation"),r.getLong("revision"),r.getString("state"),r.getBoolean("superseded"),instant(r,"valid_until"));}
    private static Evidence evidence(ResultSet r,int i)throws SQLException{return new Evidence(r.getObject("evidence_id",UUID.class),r.getObject("request_id",UUID.class),r.getObject("object_key",UUID.class),r.getObject("preview_key",UUID.class),r.getString("document_type"),r.getString("state"),instant(r,"expires_at"),instant(r,"retain_until"),r.getLong("revision"),r.getString("mime"));}
    public Instant now(){return jdbc.sql("SELECT clock_timestamp()").query(OffsetDateTime.class).single().toInstant();}
    public Optional<Request> request(UUID id,boolean lock){return sql("SELECT * FROM cinenest_verification.verification_request WHERE request_id=:id"+(lock?" FOR UPDATE":""),"id",id).query(JdbcVerificationRepository::request).optional();}
    public Optional<Evidence> evidence(UUID id,boolean lock){return sql("SELECT * FROM cinenest_verification.identity_evidence WHERE evidence_id=:id"+(lock?" FOR UPDATE":""),"id",id).query(JdbcVerificationRepository::evidence).optional();}
    public List<Evidence> evidenceFor(UUID request){return sql("SELECT * FROM cinenest_verification.identity_evidence WHERE request_id=:id ORDER BY position","id",request).query(JdbcVerificationRepository::evidence).list();}
    public List<Request> queue(UUID venue,UUID actor){return sql("SELECT * FROM cinenest_verification.verification_request WHERE venue_id=:venue AND owner_id<>:actor AND NOT superseded ORDER BY created_at DESC LIMIT 100","venue",venue,"actor",actor).query(JdbcVerificationRepository::request).list();}
    public List<Map<String,Object>> history(UUID request){return sql("SELECT decision_id,revision,verdict,reason_code,recorded_at,valid_until FROM cinenest_verification.verification_decision WHERE request_id=:id ORDER BY revision","id",request).query((r,i)->Map.<String,Object>of("id",r.getObject(1).toString(),"revision",r.getLong(2),"verdict",r.getString(3),"reason",r.getString(4),"at",r.getObject(5).toString(),"validUntil",r.getObject(6).toString())).list();}
    public void policy(VerificationPolicy.Policy p){sql("INSERT INTO cinenest_verification.verification_policy_revision VALUES(:id,:version,:hash,CAST(:policy AS jsonb),TRUE,clock_timestamp()) ON CONFLICT(policy_id) DO NOTHING","id",p.id(),"version",p.version(),"hash",p.hash(),"policy",JSONObjectUtils.toJSONString(Map.of("synthetic",true,"age",18,"maxImages",2,"maxBytes",VerificationPolicy.MAX_BYTES,"maxPixels",VerificationPolicy.MAX_PIXELS,"uploadSeconds",p.upload().toSeconds(),"retentionSeconds",p.retention().toSeconds(),"decisionSeconds",p.decision().toSeconds(),"cleanupSeconds",p.cleanup().toSeconds(),"fixtures",p.fixtures()))).update();}
    public void create(Request r){sql("INSERT INTO cinenest_verification.verification_request(request_id,owner_id,venue_id,quote_id,policy_id,previous_id,generation,revision,state) VALUES(:id,:owner,:venue,:quote,:policy,:previous,:generation,0,'NOT_SUBMITTED')","id",r.id(),"owner",r.owner(),"venue",r.venue(),"quote",r.quote(),"policy",r.policy(),"previous",r.previous(),"generation",r.generation()).update();}
    public void supersede(UUID request){sql("UPDATE cinenest_verification.verification_request SET superseded=TRUE,revision=revision+1 WHERE request_id=:id","id",request).update();}
    public void transition(UUID request,String state,Instant until){sql("UPDATE cinenest_verification.verification_request SET state=:state,revision=revision+1,valid_until=:until WHERE request_id=:id","id",request,"state",state,"until",until==null?null:OffsetDateTime.ofInstant(until,ZoneOffset.UTC)).update();}
    public void allocate(Evidence e,int position){sql("INSERT INTO cinenest_verification.identity_evidence(evidence_id,request_id,object_key,preview_key,document_type,position,state,expires_at,retain_until) VALUES(:id,:request,:object,:preview,:type,:position,'ALLOCATED',:expires,:retain)","id",e.id(),"request",e.request(),"object",e.object(),"preview",e.preview(),"type",e.type(),"position",position,"expires",OffsetDateTime.ofInstant(e.expires(),ZoneOffset.UTC),"retain",OffsetDateTime.ofInstant(e.retain(),ZoneOffset.UTC)).update();}
    public void evidenceState(UUID id,String state){sql("UPDATE cinenest_verification.identity_evidence SET state=:state,revision=revision+1 WHERE evidence_id=:id","id",id,"state",state).update();}
    public void uploaded(UUID id,String digest,String mime,long bytes){sql("UPDATE cinenest_verification.identity_evidence SET state='QUARANTINED',digest=:digest,mime=:mime,byte_size=:bytes,revision=revision+1 WHERE evidence_id=:id","id",id,"digest",digest,"mime",mime,"bytes",bytes).update();}
    public void decision(UUID id,Request r,UUID actor,String verdict,String reason,Instant until){sql("INSERT INTO cinenest_verification.verification_decision VALUES(:id,:request,:revision,:actor,:verdict,:reason,:policy,clock_timestamp(),:until)","id",id,"request",r.id(),"revision",r.revision(),"actor",actor,"verdict",verdict,"reason",reason,"policy",r.policy(),"until",OffsetDateTime.ofInstant(until,ZoneOffset.UTC)).update();sql("INSERT INTO cinenest_verification.decision_evidence SELECT request_id,:decision,evidence_id FROM cinenest_verification.identity_evidence WHERE request_id=:request AND state='READY'","decision",id,"request",r.id()).update();}
    public Optional<Map<String,Object>> command(UUID actor,UUID key,String hash){return sql("SELECT content_hash,response::text FROM cinenest_verification.verification_command WHERE actor_id=:actor AND command_key=:key","actor",actor,"key",key).query((r,i)->{if(!hash.equals(r.getString(1)))throw new VerificationFailure(409,"Command key already used for another operation");try{return JSONObjectUtils.parse(r.getString(2));}catch(java.text.ParseException invalid){throw new IllegalStateException();}}).optional();}
    public void command(UUID actor,UUID key,String hash,Map<String,Object> response){sql("INSERT INTO cinenest_verification.verification_command VALUES(:actor,:key,:hash,CAST(:response AS jsonb),clock_timestamp())","actor",actor,"key",key,"hash",hash,"response",JSONObjectUtils.toJSONString(response)).update();}
    public void audit(UUID actor,UUID request,String action,String outcome){sql("INSERT INTO cinenest_verification.verification_audit VALUES(:id,:actor,:request,:action,:outcome,:correlation,clock_timestamp())","id",UUID.randomUUID(),"actor",actor,"request",request,"action",action,"outcome",outcome,"correlation",UUID.randomUUID()).update();}
    public void work(UUID id){sql("INSERT INTO cinenest_verification.verification_work VALUES(:work,:id,'PENDING',NULL,0,clock_timestamp(),clock_timestamp()) ON CONFLICT(evidence_id) DO UPDATE SET state='PENDING',due_at=clock_timestamp()","work",UUID.randomUUID(),"id",id).update();}
    public List<UUID> pending(Instant now){return jdbc.sql("SELECT evidence_id FROM cinenest_verification.verification_work WHERE state IN ('PENDING','FAILED') OR (state='RUNNING' AND lease_until<clock_timestamp()) ORDER BY due_at LIMIT 100").query(UUID.class).list();}
    public int claim(UUID id,Instant until){return sql("UPDATE cinenest_verification.verification_work SET state='RUNNING',attempts=attempts+1,lease_until=:until,updated_at=clock_timestamp() WHERE evidence_id=:id AND (state IN ('PENDING','FAILED') OR (state='RUNNING' AND lease_until<clock_timestamp())) RETURNING attempts","id",id,"until",OffsetDateTime.ofInstant(until,ZoneOffset.UTC)).query(Integer.class).optional().orElse(0);}
    public boolean owns(UUID id,int attempt){return sql("SELECT work_id FROM cinenest_verification.verification_work WHERE evidence_id=:id AND state='RUNNING' AND attempts=:attempt FOR UPDATE","id",id,"attempt",attempt).query(UUID.class).optional().isPresent();}
    public void workState(UUID id,String state){sql("UPDATE cinenest_verification.verification_work SET state=:state,updated_at=clock_timestamp() WHERE evidence_id=:id","id",id,"state",state).update();}
    public List<Evidence> cleanup(Instant now){return jdbc.sql("SELECT * FROM cinenest_verification.identity_evidence WHERE state<>'DELETED' AND (retain_until<clock_timestamp() OR (state IN ('ALLOCATED','UPLOADING') AND expires_at<clock_timestamp()) OR state IN ('DELETION_PENDING','CLEANUP_FAILED')) ORDER BY evidence_id LIMIT 100").query(JdbcVerificationRepository::evidence).list();}
    public boolean referenced(UUID key){return sql("SELECT count(*) FROM cinenest_verification.identity_evidence WHERE (object_key=:key OR preview_key=:key) AND state<>'DELETED'","key",key).query(Integer.class).single()>0;}
}
